def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_d = 0
    my_d = 0
    r5d = 0
    r10d = 0
    for i in range(n):
        m, o = history[i]
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1
            if n - i <= 5:
                r5d += 1
            if n - i <= 10:
                r10d += 1

    coop = (n - opp_d) / n
    last_m, last_o = history[-1]

    opp_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_run += 1
        else:
            break

    my_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_run += 1
        else:
            break

    if opp_d == n or coop < 0.18 or r5d >= 4 or r10d >= 7:
        return 'D'

    if last_o == 'D':
        if opp_run == 1:
            if last_m == 'C':
                return 'D'
            if my_run <= 2 and coop > 0.70:
                return 'C' if rng.random() < 0.45 else 'D'
            return 'D'

        if opp_run == 2:
            if coop > 0.78:
                return 'C' if rng.random() < 0.28 else 'D'
            if coop > 0.50 and rng.random() < 0.05:
                return 'C'
            return 'D'

        if coop > 0.88 and opp_run == 3 and rng.random() < 0.06:
            return 'C'
        return 'D'

    if last_m == 'D':
        if coop < 0.30:
            return 'D'
        if my_run >= 3 and r10d >= 4:
            return 'D' if rng.random() < 0.50 else 'C'
        return 'C'

    if coop < 0.35 or r10d >= 5 or (r5d >= 3 and coop < 0.80):
        return 'D'

    if n >= 95:
        if r5d > 0 or coop < 0.95:
            return 'D'
        return 'C'

    return 'C'
